import sys
from typing import List, Tuple

def solve(A: int, B: int) -> Tuple[int, int, List[str]]:
    h, w = max(A, B) + 1, max(A, B) + 1
    grid = [['#' if i % 2 == j % 2 else '.' for j in range(w)] for i in range(h)]

    def dfs(i: int, j: int, color: str) -> None:
        if i < 0 or i >= h or j < 0 or j >= w or grid[i][j] != color:
            return
        grid[i][j] = color.swapcase()
        for di, dj in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            dfs(i + di, j + dj, color)

    for i in range(h):
        for j in range(w):
            if (i * w + j) % 2 == 0:
                dfs(i, j, '.')
            else:
                dfs(i, j, '#')

    return h, w, [''.join(row) for row in grid]

